207     Value *Op0 = Inst.getOperand(0);
208     if (InsertedValues.count(Op0) || !isNonNegative(Op0))
209       return false;
210     NewInst = BinaryOperator::CreateLShr(Op0, Inst.getOperand(1), "", Inst.getIterator());
211     NewInst->setIsExact(Inst.isExact());
212     break;
213   }
214   case Instruction::SDiv:
215   case Instruction::SRem: {
216     // If both operands are not negative, this is the same as udiv/urem.
217     Value *Op0 = Inst.getOperand(0), *Op1 = Inst.getOperand(1);
218     if (InsertedValues.count(Op0) || InsertedValues.count(Op1) ||
219         !isNonNegative(Op0) || !isNonNegative(Op1))
220       return false;
221     auto NewOpcode = Inst.getOpcode() == Instruction::SDiv ? Instruction::UDiv
